The FreePage function in memory/replace/phc/PHC.cpp currently has the following code:

```
#ifdef XP_WIN
  if (!VirtualFree(pagePtr, kPageSize, MEM_DECOMMIT)) {
    return;
  }
#else
  if (!mmap(pagePtr, kPageSize, PROT_NONE, MAP_FIXED | MAP_PRIVATE | MAP_ANON,
            -1, 0)) {
    return;
  }
#endif
```

Assuming that the Windows and Unix branches are supposed to do the same thing, the idea here is to return early if the function call fails. However, mmap does not return 0 on failure but rather MAP_FAILED which is defined to be -1. This means that the Unix branch will never return early even if there is an error.

The ScopedMMap class in xpcom/glue/FileUtils.cpp currently has the following code:

```
  explicit ScopedMMap(const char* aFilePath) : buf(nullptr) {
    fd = open(aFilePath, O_RDONLY);
    if (fd < 0) {
      return;
    }
    struct stat st;
    if (fstat(fd, &st) < 0) {
      return;
    }
    size = st.st_size;
    buf = (char*)mmap(nullptr, size, PROT_READ, MAP_PRIVATE, fd, 0);
  }
  ~ScopedMMap() {
    if (buf) {
      munmap(buf, size);
    }
    if (fd >= 0) {
      close(fd);
    }
  }
  operator char*() { return buf; }
```

And it is used like this:

```
  ScopedMMap buf(aFilePath);
  char* base = buf;
  if (!base) {
    return;
  }
```

However, mmap does not return 0 on failure but rather MAP_FAILED which is defined to be -1, so `!base` is always false. This means that if mmap fails, the program will segfault instead of gracefully failing.

